"""
Module for Python interpreter discovery and provisioning.

This module provides utilities to find Python interpreters across the system,
including system PATH, uv-managed installations, and conda environments.
It also supports installing Python via uv if available.
"""

import logging
import os
import re
import shutil
import subprocess
import sys
from dataclasses import dataclass, field
from pathlib import Path
from typing import Optional

logger = logging.getLogger(__name__)


@dataclass
class PythonInfo:
    """Information about a discovered Python interpreter.

    Attributes:
        path: Path to the Python executable
        version: Python version string (e.g., "3.11.7")
        source: Source of the interpreter ("system", "conda", "uv", "homebrew", "pyenv")
        is_valid: Whether the interpreter passed validation
        error: Error message if validation failed
    """

    path: Path
    version: str
    source: str
    is_valid: bool = True
    error: Optional[str] = None
    metadata: dict = field(default_factory=dict)

    @property
    def major_minor(self) -> str:
        """Return major.minor version (e.g., '3.11')."""
        parts = self.version.split(".")
        if len(parts) >= 2:
            return f"{parts[0]}.{parts[1]}"
        return self.version


def is_uv_available() -> bool:
    """Check if uv is installed and available.

    Returns:
        bool: True if uv is available, False otherwise
    """
    return shutil.which("uv") is not None


def _get_python_version(python_path: Path) -> Optional[str]:
    """Get Python version from executable.

    Args:
        python_path: Path to Python executable

    Returns:
        Version string (e.g., "3.11.7") or None if failed
    """
    try:
        result = subprocess.run(
            [str(python_path), "--version"],
            capture_output=True,
            text=True,
            timeout=10,
            check=False,
        )
        if result.returncode == 0:
            # Output is "Python 3.x.y"
            output = result.stdout.strip() or result.stderr.strip()
            if output.startswith("Python "):
                return output[7:]
            return output
    except (subprocess.TimeoutExpired, OSError, subprocess.SubprocessError) as err:
        logger.debug("Failed to get version from %s: %s", python_path, err)

    return None


def _validate_python(python_path: Path) -> tuple[bool, Optional[str]]:
    """Validate that a Python executable is working.

    Args:
        python_path: Path to Python executable

    Returns:
        tuple[bool, Optional[str]]: (is_valid, error_message)
    """
    if not python_path.exists() and not python_path.is_symlink():
        return False, f"Path does not exist: {python_path}"

    # Check for broken symlinks
    if python_path.is_symlink():
        try:
            target = python_path.resolve()
            if not target.exists():
                return False, f"Broken symlink: {python_path} -> {target}"
        except OSError as err:
            return False, f"Cannot resolve symlink: {err}"

    # Try to run python --version
    version = _get_python_version(python_path)
    if version is None:
        return False, "Failed to execute --version"

    return True, None


def _find_pythons_in_path() -> list[PythonInfo]:
    """Find Python executables in system PATH and common locations.

    Returns:
        list[PythonInfo]: List of discovered Python interpreters
    """
    pythons: list[PythonInfo] = []
    seen_paths: set[Path] = set()

    # Check common Python version patterns via which
    python_names = ["python3", "python"]
    for minor in range(9, 14):  # Python 3.9 through 3.13
        python_names.append(f"python3.{minor}")

    for name in python_names:
        found_path = shutil.which(name)
        if found_path:
            path = Path(found_path).resolve()
            if path in seen_paths:
                continue
            seen_paths.add(path)

            version = _get_python_version(path)
            if version:
                is_valid, error = _validate_python(path)
                pythons.append(
                    PythonInfo(
                        path=path,
                        version=version,
                        source="system",
                        is_valid=is_valid,
                        error=error,
                    )
                )

    # Also check common system paths that might not be in PATH
    common_paths = [
        Path("/usr/bin"),
        Path("/usr/local/bin"),
        Path("/opt/local/bin"),  # MacPorts
    ]

    for base_path in common_paths:
        if not base_path.exists():
            continue

        for minor in range(9, 14):  # Python 3.9 through 3.13
            candidate_path = base_path / f"python3.{minor}"
            if candidate_path.exists():
                resolved = candidate_path.resolve()
                if resolved in seen_paths:
                    continue
                seen_paths.add(resolved)

                version = _get_python_version(candidate_path)
                if version:
                    is_valid, error = _validate_python(candidate_path)
                    pythons.append(
                        PythonInfo(
                            path=resolved,
                            version=version,
                            source="system",
                            is_valid=is_valid,
                            error=error,
                        )
                    )

    return pythons


def _find_conda_pythons() -> list[PythonInfo]:
    """Find Python executables in conda environments.

    Returns:
        list[PythonInfo]: List of discovered Python interpreters
    """
    pythons: list[PythonInfo] = []

    try:
        result = subprocess.run(
            ["conda", "env", "list"],
            capture_output=True,
            text=True,
            timeout=30,
            check=False,
        )
        if result.returncode != 0:
            return pythons

        for line in result.stdout.strip().split("\n"):
            if not line or line.startswith("#"):
                continue

            parts = line.split()
            if len(parts) < 2:
                continue

            # Last part is the path
            env_path = Path(parts[-1])

            # Find Python in the environment
            if sys.platform == "win32":
                python_path = env_path / "python.exe"
            else:
                python_path = env_path / "bin" / "python"

            if not python_path.exists():
                continue

            version = _get_python_version(python_path)
            if version:
                is_valid, error = _validate_python(python_path)
                pythons.append(
                    PythonInfo(
                        path=python_path.resolve(),
                        version=version,
                        source="conda",
                        is_valid=is_valid,
                        error=error,
                        metadata={"env_name": parts[0].replace("*", "").strip()},
                    )
                )

    except (subprocess.TimeoutExpired, FileNotFoundError, OSError) as err:
        logger.debug("Failed to enumerate conda environments: %s", err)

    return pythons


def _find_uv_pythons() -> list[PythonInfo]:
    """Find Python executables managed by uv.

    Returns:
        list[PythonInfo]: List of discovered Python interpreters
    """
    pythons: list[PythonInfo] = []

    if not is_uv_available():
        return pythons

    try:
        result = subprocess.run(
            ["uv", "python", "list"],
            capture_output=True,
            text=True,
            timeout=30,
            check=False,
        )
        if result.returncode != 0:
            return pythons

        # Parse uv python list output
        # Format: cpython-3.11.7-macos-aarch64-none    /path/to/python
        for line in result.stdout.strip().split("\n"):
            if not line.strip():
                continue

            parts = line.split()
            if len(parts) < 2:
                continue

            # Find the path (usually last element that looks like a path)
            python_path = None
            for part in reversed(parts):
                if part.startswith("/") or (sys.platform == "win32" and ":" in part):
                    python_path = Path(part)
                    break

            if python_path is None or not python_path.exists():
                continue

            version = _get_python_version(python_path)
            if version:
                is_valid, error = _validate_python(python_path)
                pythons.append(
                    PythonInfo(
                        path=python_path.resolve(),
                        version=version,
                        source="uv",
                        is_valid=is_valid,
                        error=error,
                        metadata={"uv_name": parts[0] if parts else ""},
                    )
                )

    except (subprocess.TimeoutExpired, FileNotFoundError, OSError) as err:
        logger.debug("Failed to enumerate uv pythons: %s", err)

    return pythons


def _find_homebrew_pythons() -> list[PythonInfo]:
    """Find Python executables installed via Homebrew (macOS).

    Returns:
        list[PythonInfo]: List of discovered Python interpreters
    """
    pythons: list[PythonInfo] = []

    if sys.platform != "darwin":
        return pythons

    # Check common Homebrew paths
    homebrew_paths = [
        Path("/opt/homebrew/bin"),  # Apple Silicon
        Path("/usr/local/bin"),  # Intel
    ]

    seen_paths = set()

    for brew_bin in homebrew_paths:
        if not brew_bin.exists():
            continue

        for minor in range(9, 14):  # Python 3.9 through 3.13
            python_path = brew_bin / f"python3.{minor}"
            if python_path.exists():
                resolved = python_path.resolve()
                if resolved in seen_paths:
                    continue
                seen_paths.add(resolved)

                version = _get_python_version(python_path)
                if version:
                    is_valid, error = _validate_python(python_path)
                    pythons.append(
                        PythonInfo(
                            path=resolved,
                            version=version,
                            source="homebrew",
                            is_valid=is_valid,
                            error=error,
                        )
                    )

    return pythons


def _find_pyenv_pythons() -> list[PythonInfo]:
    """Find Python executables managed by pyenv.

    Returns:
        list[PythonInfo]: List of discovered Python interpreters
    """
    pythons: list[PythonInfo] = []

    # Check PYENV_ROOT or default location
    pyenv_root = os.environ.get("PYENV_ROOT", str(Path.home() / ".pyenv"))
    versions_dir = Path(pyenv_root) / "versions"

    if not versions_dir.exists():
        return pythons

    try:
        for version_dir in versions_dir.iterdir():
            if not version_dir.is_dir():
                continue

            if sys.platform == "win32":
                python_path = version_dir / "python.exe"
            else:
                python_path = version_dir / "bin" / "python"

            if not python_path.exists():
                continue

            version = _get_python_version(python_path)
            if version:
                is_valid, error = _validate_python(python_path)
                pythons.append(
                    PythonInfo(
                        path=python_path.resolve(),
                        version=version,
                        source="pyenv",
                        is_valid=is_valid,
                        error=error,
                        metadata={"pyenv_version": version_dir.name},
                    )
                )

    except OSError as err:
        logger.debug("Failed to enumerate pyenv versions: %s", err)

    return pythons


def _find_windows_pythons() -> list[PythonInfo]:
    """Find Python executables on Windows using py launcher.

    Returns:
        list[PythonInfo]: List of discovered Python interpreters
    """
    pythons: list[PythonInfo] = []

    if sys.platform != "win32":
        return pythons

    try:
        # Use py -0p to list installed Pythons with paths
        result = subprocess.run(
            ["py", "-0p"],
            capture_output=True,
            text=True,
            timeout=30,
            check=False,
        )
        if result.returncode != 0:
            return pythons

        # Parse output: -V:3.11 *       C:\Python311\python.exe
        for line in result.stdout.strip().split("\n"):
            if not line.strip():
                continue

            # Extract path (last element that contains .exe)
            parts = line.split()
            python_path = None
            for part in reversed(parts):
                if ".exe" in part.lower():
                    python_path = Path(part)
                    break

            if python_path is None or not python_path.exists():
                continue

            version = _get_python_version(python_path)
            if version:
                is_valid, error = _validate_python(python_path)
                pythons.append(
                    PythonInfo(
                        path=python_path.resolve(),
                        version=version,
                        source="system",
                        is_valid=is_valid,
                        error=error,
                    )
                )

    except (subprocess.TimeoutExpired, FileNotFoundError, OSError) as err:
        logger.debug("Failed to enumerate Windows pythons: %s", err)

    return pythons


def find_system_pythons(include_invalid: bool = False) -> list[PythonInfo]:
    """Find all Python interpreters on the system.

    Searches multiple sources:
    - System PATH
    - uv-managed installations
    - conda environments
    - Homebrew (macOS)
    - pyenv
    - Windows py launcher

    Args:
        include_invalid: If True, include Python interpreters that failed validation

    Returns:
        list[PythonInfo]: List of discovered Python interpreters, sorted by version
    """
    all_pythons = []
    seen_paths = set()

    # Collect from all sources
    sources = [
        _find_pythons_in_path,
        _find_uv_pythons,
        _find_conda_pythons,
        _find_homebrew_pythons,
        _find_pyenv_pythons,
    ]

    if sys.platform == "win32":
        sources.append(_find_windows_pythons)

    for finder in sources:
        try:
            for python_info in finder():
                # Deduplicate by resolved path
                if python_info.path in seen_paths:
                    continue
                seen_paths.add(python_info.path)

                if include_invalid or python_info.is_valid:
                    all_pythons.append(python_info)
        except Exception as err:  # pylint: disable=broad-exception-caught
            logger.debug("Error in Python finder %s: %s", finder.__name__, err)

    # Sort by version (newest first)
    def version_key(info: PythonInfo) -> tuple:
        try:
            parts = info.version.split(".")
            return tuple(int(p) for p in parts[:3])
        except (ValueError, IndexError):
            return (0, 0, 0)

    all_pythons.sort(key=version_key, reverse=True)

    return all_pythons


def find_python(version: str, prefer_source: Optional[str] = None) -> Optional[PythonInfo]:
    """Find a Python interpreter matching the specified version.

    Args:
        version: Version to match (e.g., "3.11", "3.11.7")
                 Matches major.minor if only two parts provided
        prefer_source: Preferred source ("uv", "conda", "system", etc.)

    Returns:
        PythonInfo for matching interpreter, or None if not found
    """
    all_pythons = find_system_pythons()

    # Normalize version for comparison
    version_parts = version.split(".")
    match_major_minor = len(version_parts) <= 2

    matches = []
    for python_info in all_pythons:
        if match_major_minor:
            if python_info.major_minor == ".".join(version_parts[:2]):
                matches.append(python_info)
        else:
            if python_info.version == version:
                matches.append(python_info)
            elif python_info.version.startswith(version):
                matches.append(python_info)

    if not matches:
        return None

    # Prefer requested source
    if prefer_source:
        for match in matches:
            if match.source == prefer_source:
                return match

    # Return first match (already sorted by version)
    return matches[0]


def install_python(version: str) -> Path:
    """Install Python using uv.

    Args:
        version: Version to install (e.g., "3.11", "3.11.7")

    Returns:
        Path to installed Python executable

    Raises:
        RuntimeError: If uv is not available
        subprocess.CalledProcessError: If installation fails
    """
    if not is_uv_available():
        raise RuntimeError(
            f"Cannot install Python {version}: uv is not available. "
            "Install uv (https://docs.astral.sh/uv/), install Python manually, "
            "or provide a path to an existing Python interpreter."
        )

    logger.info("Installing Python %s via uv...", version)

    # Install Python via uv
    result = subprocess.run(
        ["uv", "python", "install", version],
        capture_output=True,
        text=True,
        check=True,
    )

    logger.debug("uv install output: %s", result.stdout)

    # Find the newly installed Python
    python_info = find_python(version, prefer_source="uv")
    if python_info is None:
        raise RuntimeError(
            f"Python {version} installation reported success but interpreter not found"
        )

    logger.info("Installed Python %s at %s", python_info.version, python_info.path)
    return python_info.path


def get_or_install_python(version: str, auto_install: bool = True) -> Optional[Path]:
    """Get an existing Python or install if not found.

    Args:
        version: Version to find or install (e.g., "3.11")
        auto_install: If True and uv is available, install Python if not found

    Returns:
        Path to Python executable, or None if not found and cannot install

    Raises:
        RuntimeError: If Python not found and cannot be installed
    """
    # First try to find existing Python
    python_info = find_python(version)
    if python_info:
        return python_info.path

    # Try to install via uv
    if auto_install and is_uv_available():
        return install_python(version)

    # Cannot install
    if auto_install:
        raise RuntimeError(
            f"Python {version} not found. "
            "Install Python manually, install uv (https://docs.astral.sh/uv/), "
            "or provide a path to an existing Python interpreter."
        )

    return None


def extract_version_from_pyvenv_cfg(pyvenv_cfg_path: Path) -> Optional[str]:
    """Extract Python version from pyvenv.cfg file.

    Args:
        pyvenv_cfg_path: Path to pyvenv.cfg file

    Returns:
        Version string (e.g., "3.11") or None if not found
    """
    if not pyvenv_cfg_path.exists():
        return None

    try:
        with open(pyvenv_cfg_path, "r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                # Look for version = X.Y.Z or version_info = X.Y.Z
                if line.startswith("version"):
                    parts = line.split("=", 1)
                    if len(parts) == 2:
                        version = parts[1].strip()
                        # Extract major.minor
                        match = re.match(r"(\d+\.\d+)", version)
                        if match:
                            return match.group(1)
    except OSError as err:
        logger.debug("Failed to read pyvenv.cfg: %s", err)

    return None


__all__ = [
    "PythonInfo",
    "find_system_pythons",
    "find_python",
    "install_python",
    "get_or_install_python",
    "is_uv_available",
    "extract_version_from_pyvenv_cfg",
]
